    'Разделение Save/Publish предотвращает случайные изменения в продакшне',
    'Визуальный диффинг версий с бейджами счётчика изменений для безопасного ревью перед публикацией',
    'Действия чат-нода: пауза воркфлоу для одобрений human-in-the-loop при выполнении'
  ],
  cons = ARRAY[
    'Self-hosted требует настройки инфраструктуры и её обслуживания для бесплатного тарифа',
    'Более крутая кривая обучения, чем у no-code инструментов вроде Zapier для нетехнических пользователей',
    'Облачный план от $20/мес — дополнительные расходы для предпочитающих управляемый хостинг',
    'Большие библиотеки воркфлоу требуют тщательной организации — нет встроенной иерархии папок'
  ]
WHERE slug = 'n8n' AND lang = 'ru';

